import { OrderDto } from './dto';
import { toOrderDto } from './DtoMapper';
import { OrderLookupService } from './OrderLookupService';

export class GetOrderUseCase {
  constructor(private readonly lookup: OrderLookupService) {}

  execute(orderId: string): OrderDto {
    return toOrderDto(this.lookup.require(orderId));
  }
}

